def evaluate(donor_reputation, recipient_reputation, donor_action, recipient_action, my_reputation):
    # Simple Standing norm: update donor reputation based on action and recipient reputation
    if donor_action == 'cooperate':
        if recipient_reputation >= 0.0:
            target = 1.0
        else:
            target = -1.0
    else:  # defect
        if recipient_reputation < 0.0:
            target = 1.0
        else:
            target = -1.0
    # Gradual update with learning rate 0.2
    new = donor_reputation + 0.2 * (target - donor_reputation)
    # Clamp to [-1.0, 1.0]
    return max(-1.0, min(1.0, new))

def decide(my_reputation, opponent_reputation):
    # Cooperate if opponent's reputation is non-negative
    return opponent_reputation >= 0.0

def evaluate(
    donor_reputation: float,
    recipient_reputation: float,
    donor_action: str,
    recipient_action: str,
    my_reputation: float
) -> float:
    step = 0.1
    if donor_action == 'cooperate':
        if recipient_reputation >= 0.0:
            new_rep = donor_reputation + step
        else:
            new_rep = donor_reputation - step
    else:  # defect
        if recipient_reputation >= 0.0:
            new_rep = donor_reputation - step
        else:
            new_rep = donor_reputation + step
    return max(-1.0, min(1.0, new_rep))


