    donor_reputation: float,
    recipient_reputation: float,
    donor_action: str,
    recipient_action: str,
    my_reputation: float
) -> float:
    # Stern Judging norm: cooperate with good → reputation up; defect with good → down;
    # cooperate with bad → down; defect with bad → up.
    step = 0.2  # magnitude of reputation change per observation
    if donor_action == 'cooperate':
        if recipient_reputation >= 0:
            new_rep = donor_reputation + step
        else:
            new_rep = donor_reputation - step
    else:  # defect
        if recipient_reputation >= 0:
            new_rep = donor_reputation - step
        else:
            new_rep = donor_reputation + step
    # clamp to [-1.0, 1.0]
    if new_rep > 1.0:
        new_rep = 1.0
    if new_rep < -1.0:
        new_rep = -1.0
    return new_rep

