def evaluate(
    donor_reputation: float,
    recipient_reputation: float,
    donor_action: str,
    recipient_action: str,
    my_reputation: float
) -> float:
    # base step size, scaled by my own reputation
    base_step = 0.2
    step = base_step + 0.1 * my_reputation  # ranges from 0.1 to 0.3
    step = max(0.05, min(0.5, step))  # safety bounds

    if donor_action == 'cooperate':
        if recipient_reputation >= 0.2:
            new_rep = donor_reputation + step
        else:
            new_rep = donor_reputation - step
    else:  # defect
        # asymmetry: defect penalty is larger
        step_defect = step * 1.5
        if recipient_reputation >= 0.2:
            new_rep = donor_reputation - step_defect
        else:
            new_rep = donor_reputation + step_defect
    return max(-1.0, min(1.0, new_rep))


